//                struct stat *restrict statbuf, int flags);

struct stat sb;
int result;
int dirfd = AT_FDCWD;
const char *path = "reference.link";

// Standard stat behavior (flags = 0, follows symlinks)
result = newfstatat(dirfd, path, &sb, 0);

// Do not follow symlinks (like lstat())
result = newfstatat(
    dirfd,
    path,
    &sb,
    AT_SYMLINK_NOFOLLOW
);

